function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 50) return 'grid needs 1 to 50 rows.';
  const n = grid.length;
  if (grid.some(row => !Array.isArray(row) || row.length !== n)) return 'grid must be square (n rows of n values).';
  if (grid.some(row => row.some(v => !Number.isInteger(v) || v < 0 || v > 50))) return 'Each height is an integer from 0 to 50.';
  return null;
}

