function surfaceArea(grid) {
  const n = grid.length;
  let area = 0;
  for (let row = 0; row < n; row++) {
    for (let col = 0; col < n; col++) {
      const height = grid[row][col];
      if (height > 0) {
        area += 4 * height + 2;
      }
      if (row > 0) {
        area -= 2 * Math.min(height, grid[row - 1][col]);
      }
      if (col > 0) {
        area -= 2 * Math.min(height, grid[row][col - 1]);
      }
    }
  }
  return area;
}

