function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? 50 : pick(1, 5);
  const top = size === 'large' ? 50 : pick(1, 6);
  const empty = rand() * 0.5;
  const grid = [];
  for (let i = 0; i < n; i++) {
    const row = [];
    for (let j = 0; j < n; j++) row.push(rand() < empty ? 0 : pick(0, top));
    grid.push(row);
  }
  return [grid];
}
